@extends('layouts.app') @section('title','Référentiels') @section('content')<div class="page-head"><div><h1>Référentiels</h1><p>Ajouter les régions, localités et listes utilisées dans les formulaires.</p></div></div><div class="panel"><form method="POST" action="{{ route('admin.referentiels.store') }}" class="form-grid">@csrf<div class="field"><label>Type de référentiel</label><select name="type" id="ref_type"><option value="region">Région</option><option value="localite">Localité</option><option value="ogd">OGD</option><option value="processus">Processus</option><option value="provenance">Provenance</option><option value="qualification">Qualification</option></select></div><div class="field"><label>Nom / libellé</label><input name="libelle" required></div><div class="field"><label>Code (facultatif)</label><input name="code" maxlength="40"></div><div class="field" id="ref_module"><label>Module (provenance / qualification)</label><select name="module"><option value="commun">Commun</option><option value="reclamation">Réclamation</option><option value="assistance">Assistance</option></select></div><div class="field" id="region_parent"><label>Région parente (pour localité)</label><select name="region_id"><option value="">Sélectionner</option>@foreach($regions as $r)<option value="{{ $r->id }}">{{ $r->nom }}</option>@endforeach</select></div><div class="form-actions"><button class="btn primary">Ajouter</button></div></form></div><div class="grid-two">@foreach(['Régions'=>$regions,'Localités'=>$localites,'OGD'=>$ogds,'Processus'=>$processus,'Provenances'=>$provenances,'Qualifications'=>$qualifications] as $titre=>$items)<section class="panel"><h2>{{ $titre }}</h2><ul class="simple-list">@forelse($items as $item)<li>{{ $item->nom??$item->libelle }} @if(isset($item->region))<span class="muted">— {{ $item->region }}</span>@endif</li>@empty<li class="muted">Aucune donnée</li>@endforelse</ul></section>@endforeach</div>@endsection @push('scripts')<script>const refType=document.